1	package payflow
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"math"
10		"os"
11		"path/filepath"
12		"sort"
13		"sync"
14	)
15	
16	// 账本磁盘格式（单文件，一个 JSON 文档，末附 sha256 校验和）：
17	//
18	//	{"version":1,
19	//	 "initial_balances":[{"account":"aa","asset":"usdc","balance":1000}],
20	//	 "balances":[{"account":"aa","asset":"usdc","balance":700}],
21	//	 "settlements":[{...一笔成功结算及其当时费率...}],
22	//	 "refunds":[{...一笔成功全额退款...}],
23	//	 "checksum":"<sha256 of the document without checksum>"}
24	//
25	// initial_balances 在初始化时冻结，用于检测任何对历史余额/记录的篡改；
26	// checksum 覆盖截断、比特翻转与所有语义编辑。
27	//
28	// refunds 字段缺省（旧版账本没有该字段）即视为空列表：旧文件可直接打开；
29	// 只要账本没有发生退款，写回时该字段继续缺省，读取旧账本不会改写文件。
30	//
31	// 写入采用“临时文件 + fsync + 原子 rename + 目录 fsync”，
32	// 因此崩溃后磁盘上只会存在完整的旧版本或完整新版本，
33	// 不会出现“扣款/退款无记录”或“记录未改余额”的中间状态。
34	const ledgerVersion = 1
35	
36	// 结算结果状态，与命令行输出一一对应，可分别识别。
37	const (
38		StatusSettled         = "settled"              // 成功扣款
39		StatusDuplicate       = "duplicate"            // 幂等重试：字段与原记录一致，返回原结算/原退款，不再入账
40		StatusConflict        = "conflict"             // 编号冲突：编号已成功但字段或费率/目标或原因不同
41		StatusState           = "state_error"          // 非 pending
42		StatusFunds           = "insufficient_balance" // 余额不足（含不存在的账户/资产组合）
43		StatusLimitExceeded   = "limit_exceeded"       // 本次批次该 (账户, 资产) 组合的扣款上限不足
44		StatusInvalid         = "invalid_parameter"
45		StatusStorage         = "storage_error"
46		StatusRefundSuccess   = "refunded"         // 成功全额退回
47		StatusNotFound        = "not_found"        // 退款目标结算不存在（含原付款只曾失败）
48		StatusAlreadyRefunded = "already_refunded" // 原付款已被其他退款编号全额退回
49	)
50	
51	// 拒绝原因。
52	const (
53		reasonEmptyID         = "intent id must not be empty"
54		reasonEmptyAccount    = "account must not be empty"
55		reasonEmptyAsset      = "asset must not be empty"
56		reasonBadAmount       = "amount must be a positive int64"
57		reasonOverflow        = "amount plus fee overflows int64"
58		reasonNotPending      = "intent is not pending"
59		reasonFunds           = "insufficient balance for amount plus fee"
60		reasonLimitExceeded   = "charge limit exceeded for %s/%s: max_charged %d, used %d, this item charges %d"
61		reasonDuplicate       = "duplicate settlement attempt"
62		reasonConflict        = "settlement id conflicts with a different request"
63		reasonEmptyRefundID   = "refund id must not be empty"
64		reasonEmptySettlement = "settlement_id must not be empty"
65		reasonEmptyReason     = "refund reason must not be empty"
66		reasonSettlementGone  = "settlement %q not found"
67		reasonAlreadyRefunded = "settlement %q has already been refunded by %q"
68		reasonRefundConflict  = "refund id conflicts with a different request"
69		reasonDuplicateRefund = "duplicate refund attempt"
70	)
71	
72	// BalanceInit 是初始化时一个 (账户, 资产) 组合的起始余额。
73	type BalanceInit struct {
74		Account string `json:"account"`
75		Asset   string `json:"asset"`
76		Balance int64  `json:"balance"`
77	}
78	
79	// PaymentIntent 是批次中的一项付款请求。金额使用指针以区分“缺省/null”与 0。
80	type PaymentIntent struct {
81		ID        string `json:"id"`
82		Account   string `json:"account"`
83		Paymaster string `json:"paymaster"`
84		Asset     string `json:"asset"`
85		Amount    *int64 `json:"amount"`
86		Nonce     uint64 `json:"nonce"`
87		State     string `json:"state"`
88	}
89	
90	// ChargeLimit 是本次提交中一个 (账户, 资产) 组合的扣款上限：该组合在本批次内
91	// 成功落账的 charged（付款金额 + 手续费）累计不得超过 max_charged。
92	// 上限仅对本次提交有效，不持久化；历史扣款与退款都不占本次额度。
93	// MaxCharged 使用指针以区分“缺省/null”与显式给出的 0（0 表示禁止该组合新增扣款）。
94	type ChargeLimit struct {
95		Account    string `json:"account"`
96		Asset      string `json:"asset"`
97		MaxCharged *int64 `json:"max_charged"`
98	}
99	
100	// FeeBatch 是一次提交：固定费率（基点）+ 有序意图列表 + 可选的本次扣款上限。
101	// Limits 缺省、为 null 或为空数组时不限制扣款。
102	type FeeBatch struct {
103		FeeBps  int             `json:"fee_bps"`
104		Intents []PaymentIntent `json:"intents"`
105		Limits  []ChargeLimit   `json:"limits,omitempty"`
106	}
107	
108	// Record 是一笔成功结算留下的永久记录，按成功先后顺序保存。
109	type Record struct {
110		ID        string `json:"id"`
111		Account   string `json:"account"`
112		Paymaster string `json:"paymaster"`
113		Asset     string `json:"asset"`
114		Amount    int64  `json:"amount"`
115		Nonce     uint64 `json:"nonce"`
116		FeeBps    int    `json:"fee_bps"`
117		Fee       int64  `json:"fee"`
118		Charged   int64  `json:"charged"`
119		Seq       int64  `json:"seq"`
120	}
121	
122	// ItemResult 是批次中一项的处理结果，顺序与输入逐项对应。
123	type ItemResult struct {
124		ID     string  `json:"id"`
125		Status string  `json:"status"`
126		Reason string  `json:"reason,omitempty"`
127		Record *Record `json:"record,omitempty"`
128	}
129	
130	// BatchResult 是一次提交的结果。空批次对应空 Results。
131	type BatchResult struct {
132		Results []ItemResult `json:"results"`
133	}
134	
135	// PreviewResult 是一次提交预览（--dry-run）的结果。DryRun 恒为 true，
136	// 用于与真实提交输出区分；Results 与输入逐项对应，状态、失败原因与结算
137	// 记录格式与 Submit 完全一致——其中 settled 表示“按当前账本预计能够成功”，
138	// 携带的记录使用从当前最大付款序号之后连续递增的预计序号。
139	// 预览不写入账本，序号、余额与本批次额度都不会被预留。
140	type PreviewResult struct {
141		DryRun  bool         `json:"dry_run"`
142		Results []ItemResult `json:"results"`
143	}
144	
145	// RefundRequest 是退款批次中的一项：退款编号、原付款编号、退款原因，三者均须非空。
146	type RefundRequest struct {
147		ID           string `json:"id"`
148		SettlementID string `json:"settlement_id"`
149		Reason       string `json:"reason"`
150	}
151	
152	// RefundBatch 是一次退款提交：有序的退款请求列表。
153	type RefundBatch struct {
154		Refunds []RefundRequest `json:"refunds"`
155	}
156	
157	// RefundRecord 是一笔成功全额退款留下的永久记录，按退款成功先后顺序保存。
158	// 退款金额与去向（账户/资产/总额）全部由原结算记录确定，因此一并冗余记录，
159	// 使每条退款都能脱离上下文自解释、可追溯原结算。
160	// AfterSeq 是退款落账时结算历史的长度：余额校验要求该结算在此时点之前发生。
161	type RefundRecord struct {
162		ID           string `json:"id"`
163		SettlementID string `json:"settlement_id"`
164		Reason       string `json:"reason"`
165		Account      string `json:"account"`
166		Asset        string `json:"asset"`
167		Amount       int64  `json:"amount"`
168		Fee          int64  `json:"fee"`
169		Charged      int64  `json:"charged"`
170		AfterSeq     int64  `json:"after_seq"`
171		Seq          int64  `json:"seq"`
172	}
173	
174	// RefundResult 是一项退款的处理结果。成功与幂等重复携带原付款编号、账户、
175	// 资产、退款总额与原因；失败只带状态与说明。
176	type RefundResult struct {
177		ID           string        `json:"id"`
178		Status       string        `json:"status"`
179		Reason       string        `json:"reason,omitempty"`
180		SettlementID string        `json:"settlement_id,omitempty"`
181		Account      string        `json:"account,omitempty"`
182		Asset        string        `json:"asset,omitempty"`
183		Charged      int64         `json:"charged,omitempty"`
184		Record       *RefundRecord `json:"record,omitempty"`
185	}
186	
187	// RefundBatchResult 是一次退款提交的结果，顺序与输入逐项对应。
188	type RefundBatchResult struct {
189		Results []RefundResult `json:"results"`
190	}
191	
192	// BalanceView 是一个 (账户, 资产) 组合的当前余额。
193	type BalanceView struct {
194		Account string `json:"account"`
195		Asset   string `json:"asset"`
196		Balance int64  `json:"balance"`
197	}
198	
199	// Snapshot 是账本查询结果。Refunds 按退款成功先后排列，无退款时为空列表。
200	type Snapshot struct {
201		Balances    []BalanceView  `json:"balances"`
202		Settlements []Record       `json:"settlements"`
203		Refunds     []RefundRecord `json:"refunds"`
204	}
205	
206	// LedgerError 携带可机读分类（与 ItemResult.Status 对齐）和说明。
207	type LedgerError struct {
208		Kind    string
209		Message string
210	}
211	
212	func (e *LedgerError) Error() string { return e.Kind + ": " + e.Message }
213	
214	// 错误分类。
215	const (
216		ErrInvalid = "invalid_parameter"
217		ErrExists  = "ledger_exists"
218		ErrCorrupt = "corrupt_ledger"
219		ErrStorage = "storage_error"
220		ErrClosed  = "ledger_closed"
221		ErrNotInit = "ledger_not_initialized"
222	)
223	
224	func ledgerError(kind, format string, args ...any) error {
225		return &LedgerError{Kind: kind, Message: fmt.Sprintf(format, args...)}
226	}
227	
228	// KindOf 返回错误的分类；非账本错误按存储错误处理。
229	func KindOf(err error) string {
230		var le *LedgerError
231		if errors.As(err, &le) {
232			return le.Kind
233		}
234		return ErrStorage
235	}
236	
237	// FailWriter 注入存储故障：返回 true 时本次持久化失败，
238	// 内存状态必须回滚到该项执行之前。仅用于测试。
239	type FailWriter interface {
240		FailNextPersist() bool
241	}
242	
243	type balanceKey struct {
244		account string
245		asset   string
246	}
247	
248	type ledgerState struct {
249		Version     int
250		Initial     map[balanceKey]int64 // 初始化时冻结的起始余额，仅用于完整性校验
251		Balances    map[balanceKey]int64 // 当前余额
252		Settlements []Record
253		Refunds     []RefundRecord
254	}
255	
256	// 磁盘文档字段（顺序即签名时的规范顺序，不得调整，否则旧文件校验失败）。
257	// Refunds 使用 omitempty：旧版账本缺省该字段即可读入为 nil（视为空），
258	// 且无退款的账本写回时继续省略该字段。
259	type unsignedDoc struct {
260		Version     int            `json:"version"`
261		Initial     []BalanceView  `json:"initial_balances"`
262		Balances    []BalanceView  `json:"balances"`
263		Settlements []Record       `json:"settlements"`
264		Refunds     []RefundRecord `json:"refunds,omitempty"`
265	}
266	
267	type signedDoc struct {
268		unsignedDoc
269		Checksum string `json:"checksum"`
270	}
271	
272	func balanceList(m map[balanceKey]int64) []BalanceView {
273		out := make([]BalanceView, 0, len(m))
274		for k, v := range m {
275			out = append(out, BalanceView{Account: k.account, Asset: k.asset, Balance: v})
276		}
277		sortBalances(out)
278		return out
279	}
280	
281	func balanceMap(list []BalanceView) (map[balanceKey]int64, error) {
282		out := make(map[balanceKey]int64, len(list))
283		for i, b := range list {
284			if b.Account == "" || b.Asset == "" {
285				return nil, ledgerError(ErrCorrupt, "balance %d has empty account or asset", i)
286			}
287			if b.Balance < 0 {
288				return nil, ledgerError(ErrCorrupt, "negative balance for %s/%s", b.Account, b.Asset)
289			}
290			k := balanceKey{b.Account, b.Asset}
291			if _, dup := out[k]; dup {
292				return nil, ledgerError(ErrCorrupt, "duplicate balance entry for %s/%s", b.Account, b.Asset)
293			}
294			out[k] = b.Balance
295		}
296		return out, nil
297	}
298	
299	// MarshalJSON 输出带 sha256 校验和的单个 JSON 文档。
300	func (s *ledgerState) MarshalJSON() ([]byte, error) {
301		settlements := s.Settlements
302		if settlements == nil {
303			settlements = []Record{}
304		}
305		doc := unsignedDoc{
306			Version:     s.Version,
307			Initial:     balanceList(s.Initial),
308			Balances:    balanceList(s.Balances),
309			Settlements: settlements,
310			Refunds:     s.Refunds, // nil 时因 omitempty 省略，保持无退款账本的旧格式
311		}
312		payload, err := json.Marshal(doc)
313		if err != nil {
314			return nil, err
315		}
316		sum := checksumHex(payload)
317		out := make([]byte, 0, len(payload)+len(sum)+16)
318		out = append(out, payload[:len(payload)-1]...) // 去掉结尾 '}'
319		out = append(out, []byte(`,"checksum":"`+sum+`"}`)...)
320		return out, nil
321	}
322	
323	// UnmarshalJSON 校验 checksum、结构不变式并重放全部记录。
324	func (s *ledgerState) UnmarshalJSON(data []byte) error {
325		var doc signedDoc
326		if err := json.Unmarshal(data, &doc); err != nil {
327			return err
328		}
329		if doc.Checksum == "" {
330			return ledgerError(ErrCorrupt, "missing checksum")
331		}
332		payload, err := json.Marshal(doc.unsignedDoc)
333		if err != nil {
334			return ledgerError(ErrCorrupt, "re-encode ledger: %v", err)
335		}
336		if got := checksumHex(payload); got != doc.Checksum {
337			return ledgerError(ErrCorrupt, "checksum mismatch: file %s, want %s", doc.Checksum, got)
338		}
339		if doc.Version != ledgerVersion {
340			return ledgerError(ErrCorrupt, "unsupported ledger version %d", doc.Version)
341		}
342		initial, err := balanceMap(doc.Initial)
343		if err != nil {
344			return err
345		}
346		current, err := balanceMap(doc.Balances)
347		if err != nil {
348			return err
349		}
350		records := doc.Settlements
351		if records == nil {
352			records = []Record{}
353		}
354		refunds := doc.Refunds // 旧版账本缺省该字段，nil 视为空列表
355		if refunds == nil {
356			refunds = []RefundRecord{}
357		}
358		if err := validateAndReplay(initial, current, records, refunds); err != nil {
359			return err
360		}
361		s.Version = doc.Version
362		s.Initial = initial
363		s.Balances = current
364		s.Settlements = records
365		s.Refunds = refunds
366		return nil
367	}
368	
369	func decodeState(data []byte) (*ledgerState, error) {
370		var state ledgerState
371		if err := json.Unmarshal(data, &state); err != nil {
372			if le, ok := err.(*LedgerError); ok && le.Kind == ErrCorrupt {
373				return nil, err
374			}
375			return nil, ledgerError(ErrCorrupt, "parse ledger: %v", err)
376		}
377		return &state, nil
378	}
379	
380	// CreateLedger 在 path 处创建新账本。所有初始数据先校验，
381	// 任一不合法则返回 ErrInvalid 且不创建任何文件；
382	// 路径上已有账本则返回 ErrExists，绝不覆盖历史。
383	func CreateLedger(path string, init []BalanceInit) error {
384		if err := validateInitial(init); err != nil {
385			return err
386		}
387		abs, err := filepath.Abs(path)
388		if err != nil {
389			return ledgerError(ErrStorage, "resolve path: %v", err)
390		}
391	
392		openMu.Lock()
393		defer openMu.Unlock()
394	
395		if _, err := os.Stat(abs); err == nil {
396			return ledgerError(ErrExists, "ledger already exists at %s", abs)
397		} else if !errors.Is(err, os.ErrNotExist) {
398			return ledgerError(ErrStorage, "stat %s: %v", abs, err)
399		}
400		if openRegistry[abs] != nil {
401			return ledgerError(ErrExists, "ledger is already initialized in this process")
402		}
403	
404		state := &ledgerState{
405			Version:     ledgerVersion,
406			Initial:     make(map[balanceKey]int64, len(init)),
407			Balances:    make(map[balanceKey]int64, len(init)),
408			Settlements: []Record{},
409			Refunds:     []RefundRecord{},
410		}
411		for _, b := range init {
412			k := balanceKey{b.Account, b.Asset}
413			state.Initial[k] = b.Balance
414			state.Balances[k] = b.Balance
415		}
416		if err := atomicWrite(abs, state); err != nil {
417			return err
418		}
419		openRegistry[abs] = &registryEntry{state: state}
420		return nil
421	}
422	
423	func validateInitial(init []BalanceInit) error {
424		seen := map[balanceKey]bool{}
425		for i, b := range init {
426			if b.Account == "" {
427				return ledgerError(ErrInvalid, "initial balance %d: account must not be empty", i)
428			}
429			if b.Asset == "" {
430				return ledgerError(ErrInvalid, "initial balance %d: asset must not be empty", i)
431			}
432			if b.Balance < 0 {
433				return ledgerError(ErrInvalid, "initial balance %d (%s/%s): balance must be non-negative", i, b.Account, b.Asset)
434			}
435			k := balanceKey{b.Account, b.Asset}
436			if seen[k] {
437				return ledgerError(ErrInvalid, "initial balance %d: duplicate entry for %s/%s", i, b.Account, b.Asset)
438			}
439			seen[k] = true
440		}
441		return nil
442	}
443	
444	// Ledger 是一个可持久化的本地账本。同一进程内同一路径的多次 Open
445	// 返回共享同一状态与互斥锁的实例，因此并发提交按同一本账本串行化。
446	type Ledger struct {
447		path string
448		reg  *registryEntry
449		open bool
450	}
451	
452	type registryEntry struct {
453		mu       sync.Mutex // 保护 state；整个批次串行持有
454		state    *ledgerState
455		refs     int        // 打开的句柄数
456		ops      int        // 正在执行的 Submit/Query 数
457		failHook FailWriter // 仅测试注入
458	}
459	
460	// tryEvict 仅在没有句柄且没有在途操作时注销注册表项。
461	// 调用方必须持有 openMu。
462	func tryEvict(path string, reg *registryEntry) {
463		if reg.refs == 0 && reg.ops == 0 && openRegistry[path] == reg {
464			delete(openRegistry, path)
465		}
466	}
467	
468	var (
469		openMu       sync.Mutex
470		openRegistry = map[string]*registryEntry{}
471	)
472	
473	// Open 打开（或复用）path 处的账本。账本必须已由 CreateLedger 初始化；
474	// 文件缺失返回 ErrNotInit，内容损坏返回 ErrCorrupt，不会被当成空账本重来。
475	func Open(path string) (*Ledger, error) {
476		abs, err := filepath.Abs(path)
477		if err != nil {
478			return nil, ledgerError(ErrStorage, "resolve path: %v", err)
479		}
480	
481		openMu.Lock()
482		defer openMu.Unlock()
483	
484		if reg := openRegistry[abs]; reg != nil {
485			reg.refs++
486			return &Ledger{path: abs, reg: reg, open: true}, nil
487		}
488	
489		data, err := os.ReadFile(abs)
490		if err != nil {
491			if errors.Is(err, os.ErrNotExist) {
492				return nil, ledgerError(ErrNotInit, "no ledger at %s; initialize it first", abs)
493			}
494			return nil, ledgerError(ErrStorage, "read %s: %v", abs, err)
495		}
496		if len(bytes.TrimSpace(data)) == 0 {
497			return nil, ledgerError(ErrCorrupt, "ledger file %s is empty", abs)
498		}
499		dec := json.NewDecoder(bytes.NewReader(data))
500		var rawDoc json.RawMessage
501		if err := dec.Decode(&rawDoc); err != nil {
502			return nil, ledgerError(ErrCorrupt, "parse %s: %v", abs, err)
503		}
504		// 不允许尾随内容：防止文件被拼接/截断后被误读为合法。
505		if tok, err := dec.Token(); err != io.EOF {
506			if err == nil {
507				return nil, ledgerError(ErrCorrupt, "unexpected trailing data after ledger document (token %v)", tok)
508			}
509			return nil, ledgerError(ErrCorrupt, "trailing data after ledger document: %v", err)
510		}
511		state, err := decodeState(rawDoc)
512		if err != nil {
513			return nil, err
514		}
515	
516		reg := &registryEntry{state: state, refs: 1}
517		openRegistry[abs] = reg
518		return &Ledger{path: abs, reg: reg, open: true}, nil
519	}
520	
521	// Close 释放句柄；同一进程可再次 Open 同一文件并继续使用。
522	// 若关闭时有在途提交，注册表项保留到在途操作结束，避免并发 Open
523	// 从磁盘重新加载而丢失正在写入的状态。
524	func (l *Ledger) Close() error {
525		openMu.Lock()
526		defer openMu.Unlock()
527		if !l.open {
528			return nil
529		}
530		l.open = false
531		l.reg.refs--
532		tryEvict(l.path, l.reg)
533		return nil
534	}
535	
536	// beginOp 标记一次在途操作。返回 nil 表示句柄已关闭。
537	func (l *Ledger) beginOp() error {
538		openMu.Lock()
539		defer openMu.Unlock()
540		if !l.open {
541			return ledgerError(ErrClosed, "ledger handle is closed")
542		}
543		l.reg.ops++
544		return nil
545	}
546	
547	func (l *Ledger) endOp() {
548		openMu.Lock()
549		defer openMu.Unlock()
550		l.reg.ops--
551		tryEvict(l.path, l.reg)
552	}
553	
554	// feeFor 计算手续费：amount*feeBps/10000 向下取整。
555	// amount>0、0<=feeBps<=10000 时朴素乘积可能溢出 int64，
556	// 拆成商和余数两部分即可在 int64 内精确完成。
557	func feeFor(amount int64, feeBps int) int64 {
558		hi := amount / 10000
559		lo := amount % 10000
560		return hi*int64(feeBps) + (lo*int64(feeBps))/10000
561	}
562	
563	func validateIntent(it PaymentIntent) (int64, string, bool) {
564		if it.ID == "" {
565			return 0, reasonEmptyID, false
566		}
567		if it.Account == "" {
568			return 0, reasonEmptyAccount, false
569		}
570		if it.Asset == "" {
571			return 0, reasonEmptyAsset, false
572		}
573		if it.Amount == nil || *it.Amount <= 0 {
574			return 0, reasonBadAmount, false
575		}
576		return *it.Amount, "", true
577	}
578	
579	// validateLimits 校验本次提交的扣款上限：账户与资产必须非空，同一组合不得重复，
580	// max_charged 必须明确提供且为非负 int64。任一不合法则整个批次拒绝（ErrInvalid），
581	// 与意图列表是否为空无关。合法时返回按组合索引的上限表；无上限时返回 nil。
582	func validateLimits(limits []ChargeLimit) (map[balanceKey]int64, error) {
583		if len(limits) == 0 {
584			return nil, nil
585		}
586		out := make(map[balanceKey]int64, len(limits))
587		for i, l := range limits {
588			if l.Account == "" {
589				return nil, ledgerError(ErrInvalid, "limit %d: account must not be empty", i)
590			}
591			if l.Asset == "" {
592				return nil, ledgerError(ErrInvalid, "limit %d: asset must not be empty", i)
593			}
594			if l.MaxCharged == nil {
595				return nil, ledgerError(ErrInvalid, "limit %d (%s/%s): max_charged must be provided", i, l.Account, l.Asset)
596			}
597			if *l.MaxCharged < 0 {
598				return nil, ledgerError(ErrInvalid, "limit %d (%s/%s): max_charged must be non-negative, got %d", i, l.Account, l.Asset, *l.MaxCharged)
599			}
600			k := balanceKey{l.Account, l.Asset}
601			if _, dup := out[k]; dup {
602				return nil, ledgerError(ErrInvalid, "limit %d: duplicate entry for %s/%s", i, l.Account, l.Asset)
603			}
604			out[k] = *l.MaxCharged
605		}
606		return out, nil
607	}
608	
609	// Submit 按输入顺序结算一个批次。各项独立成功或失败：后项看到前项
610	// 成功后的余额；任一项失败不影响其余项（存储错误只回滚出错项本身，
611	// 已完成的前项不回滚）。结果与输入逐项对应，空批次返回空结果。
612	//
613	// 若批次携带 limits，则每个列出的 (账户, 资产) 组合在本次提交内的成功扣款
614	// 累计（含手续费）不得超过其 max_charged：超限的项返回 limit_exceeded，
615	// 不扣余额、不留记录、不占编号与额度；未列出的组合不限制。额度按本次提交
616	// 从零计算，只有成功落账的扣款消耗额度，历史扣款与退款均不计入。
617	func (l *Ledger) Submit(batch FeeBatch) (*BatchResult, error) {
618		if err := l.beginOp(); err != nil {
619			return nil, err
620		}
621		defer l.endOp()
622		limits, err := validateBatch(batch)
623		if err != nil {
624			return nil, err
625		}
626	
627		l.reg.mu.Lock()
628		defer l.reg.mu.Unlock()
629	
630		results := l.runBatch(batch, limits, l.reg.state, true)
631		return &BatchResult{Results: results}, nil
632	}
633	
634	// Preview 在不写入账本的前提下，按当前账本预计算一个批次的结算结果，
635	// 语义与 Submit 逐项一致（状态、失败原因、结算记录格式均相同）：
636	//   - 后项看到前项“预计成功”后的可用余额与本批次已用限额；
637	//   - 预计成功的新付款使用从当前最大付款序号之后连续递增的序号，
638	//     失败、重复、冲突不消耗序号；
639	//   - 已有成功编号仍按原付款字段与费率判断重复或冲突（原付款已退款也一样），
640	//     重复项携带原记录，不占余额与本批次额度；本批次首次预计成功的编号对
641	//     后续项同样生效（相同请求重复、字段不同冲突），失败项不占编号；
642	//   - 手续费、金额溢出、状态与限额判断沿用实际提交规则，同时超限与余额不足
643	//     仍先报告超限，限额只累计本次预计成功的扣款（含手续费）。
644	//
645	// 预览全程在当前状态的深拷贝上进行：不持久化、不修改真实余额与历史，
646	// 任何编号、序号和额度都不被预留；连续预览相同批次（账本未变化）结果一致，
647	// 随后真实提交仍按首次提交处理。预览只预测业务结果，不承诺真实提交时的
648	// 写入成功（因此预览结果中不会出现 storage_error）。费率或限额非法属于
649	// 批次级错误，返回 invalid_parameter 且不产生部分结果（空批次同样检查）。
650	func (l *Ledger) Preview(batch FeeBatch) (*PreviewResult, error) {
651		if err := l.beginOp(); err != nil {
652			return nil, err
653		}
654		defer l.endOp()
655		limits, err := validateBatch(batch)
656		if err != nil {
657			return nil, err
658		}
659	
660		l.reg.mu.Lock()
661		defer l.reg.mu.Unlock()
662	
663		// 在快照副本上模拟：预览结束后真实状态与磁盘文件保持原样。
664		sim := cloneState(l.reg.state)
665		results := l.runBatch(batch, limits, sim, false)
666		return &PreviewResult{DryRun: true, Results: results}, nil
667	}
668	
669	// validateBatch 执行批次级校验：费率范围与本次扣款上限。任一不合法都返回
670	// 批次级错误（invalid_parameter），调用方不得执行任何意图（空批次同样检查）。
671	func validateBatch(batch FeeBatch) (map[balanceKey]int64, error) {
672		if batch.FeeBps < 0 || batch.FeeBps > 10000 {
673			return nil, ledgerError(ErrInvalid, "fee_bps must be within [0,10000], got %d", batch.FeeBps)
674		}
675		// 限额非法是批次级错误：任何意图都不执行（空意图列表同样检查）。
676		return validateLimits(batch.Limits)
677	}
678	
679	// runBatch 按输入顺序在给定状态 st 上处理整个批次，返回逐项结果。
680	// persist 为 true 时（真实提交）每笔预计成功都先写入 st 再原子落盘，
681	// 落盘失败回滚该项并报告 storage_error；为 false 时（预览）只在 st
682	// （应为独立副本）上推进内存状态、绝不触碰磁盘，因此不会产生存储错误。
683	// 调用方必须持有 reg.mu。
684	func (l *Ledger) runBatch(batch FeeBatch, limits map[balanceKey]int64, st *ledgerState, persist bool) []ItemResult {
685		out := make([]ItemResult, 0, len(batch.Intents))
686	
687		// 本次批次内各组合已消耗的额度，从零开始，仅预计成功的扣款计入。
688		used := make(map[balanceKey]int64, len(limits))
689	
690		for i := range batch.Intents {
691			it := &batch.Intents[i]
692			res := ItemResult{ID: it.ID}
693	
694			// 1. 参数校验。未通过的编号不占用去重资格。
695			amount, reason, ok := validateIntent(*it)
696			if !ok {
697				res.Status = StatusInvalid
698				res.Reason = reason
699				out = append(out, res)
700				continue
701			}
702	
703			// 2. 已成功编号：字段与费率完全一致则幂等返回原记录；
704			//    任一不同则编号冲突。两者都不再扣款、不改原记录。
705			//    本批次内先（预计）成功的同编号项也在此被看到。
706			if rec, exists := findRecordIn(st.Settlements, it.ID); exists {
707				if sameRequest(rec, it, amount, batch.FeeBps) {
708					cp := rec
709					res.Status = StatusDuplicate
710					res.Reason = reasonDuplicate
711					res.Record = &cp
712				} else {
713					res.Status = StatusConflict
714					res.Reason = reasonConflict
715				}
716				out = append(out, res)
717				continue
718			}
719	
720			// 3. 状态错误单独报告（不占用去重资格，之后可重新提交）。
721			if it.State != "" && it.State != "pending" {
722				res.Status = StatusState
723				res.Reason = reasonNotPending
724				out = append(out, res)
725				continue
726			}
727	
728			// 4. 手续费与扣款总额（溢出明确按参数错误拒绝）。
729			fee := feeFor(amount, batch.FeeBps)
730			if fee > math.MaxInt64-amount {
731				res.Status = StatusInvalid
732				res.Reason = reasonOverflow
733				out = append(out, res)
734				continue
735			}
736			total := amount + fee
737	
738			key := balanceKey{it.Account, it.Asset}
739	
740			// 5. 本次批次限额（先于余额判断：同时超限与余额不足时报告超限）。
741			//    恰好达到上限仍允许；用 total > max-used 而非 used+total > max，
742			//    避免累计接近 int64 上界时溢出放行。失败不消耗额度。
743			if max, capped := limits[key]; capped {
744				if u := used[key]; total > max-u {
745					res.Status = StatusLimitExceeded
746					res.Reason = fmt.Sprintf(reasonLimitExceeded, it.Account, it.Asset, max, u, total)
747					out = append(out, res)
748					continue
749				}
750			}
751	
752			// 6. 余额校验。不存在的账户/资产组合余额视为 0（不足）。
753			bal := st.Balances[key]
754			if total > bal {
755				res.Status = StatusFunds
756				res.Reason = reasonFunds
757				out = append(out, res)
758				continue
759			}
760	
761			// 7. 预计成功：构造记录（序号按当前模拟历史长度连续递增）。
762			rec := Record{
763				ID:        it.ID,
764				Account:   it.Account,
765				Paymaster: it.Paymaster,
766				Asset:     it.Asset,
767				Amount:    amount,
768				Nonce:     it.Nonce,
769				FeeBps:    batch.FeeBps,
770				Fee:       fee,
771				Charged:   total,
772				Seq:       int64(len(st.Settlements)) + 1,
773			}
774	
775			if persist {
776				// 真实提交：先在内存生效，再原子持久化；保存失败回滚该项，
777				// 不留成功记录、不占额度。
778				rollback := stageOn(st, key, bal-total, rec)
779				if err := l.persistLocked(); err != nil {
780					rollback()
781					res.Status = StatusStorage
782					res.Reason = err.Error()
783					out = append(out, res)
784					continue
785				}
786			} else {
787				// 预览：只推进副本状态，绝不落盘。
788				st.Balances[key] = bal - total
789				st.Settlements = append(st.Settlements, rec)
790			}
791	
792			// 只有（预计）成功的扣款消耗额度；预览同样如此。
793			used[key] += total
794			cp := rec
795			res.Status = StatusSettled
796			res.Record = &cp
797			out = append(out, res)
798		}
799		return out
800	}
801	
802	// cloneState 返回账本状态的独立深拷贝，供预览在副本上模拟而不触碰真实状态。
803	func cloneState(st *ledgerState) *ledgerState {
804		cp := &ledgerState{
805			Version:     st.Version,
806			Initial:     make(map[balanceKey]int64, len(st.Initial)),
807			Balances:    make(map[balanceKey]int64, len(st.Balances)),
808			Settlements: append([]Record(nil), st.Settlements...),
809			Refunds:     append([]RefundRecord(nil), st.Refunds...),
810		}
811		for k, v := range st.Initial {
812			cp.Initial[k] = v
813		}
814		for k, v := range st.Balances {
815			cp.Balances[k] = v
816		}
817		return cp
818	}
819	
820	// findRecordIn 在给定结算历史中按编号查找成功记录。
821	func findRecordIn(records []Record, id string) (Record, bool) {
822		// 记录按成功顺序追加且 ID 唯一；单机账本量级直接扫描。
823		for _, r := range records {
824			if r.ID == id {
825				return r, true
826			}
827		}
828		return Record{}, false
829	}
830	
831	// stageOn 在指定状态上应用一笔扣款与记录，返回回滚函数（恢复该项执行前的
832	// 余额与记录长度）。
833	func stageOn(st *ledgerState, key balanceKey, newBal int64, rec Record) func() {
834		oldBal, hadKey := st.Balances[key]
835		oldLen := len(st.Settlements)
836		st.Balances[key] = newBal
837		st.Settlements = append(st.Settlements, rec)
838		return func() {
839			if hadKey {
840				st.Balances[key] = oldBal
841			} else {
842				delete(st.Balances, key)
843			}
844			st.Settlements = st.Settlements[:oldLen]
845		}
846	}
847	
848	// Refund 按输入顺序处理一个退款批次。各项独立处理：后项能看到前项成功退回的
849	// 余额；任一项失败不影响其余项（存储错误只回滚出错项本身，前项保留，后项继续）。
850	// 结果与输入逐项对应，空批次返回空结果。
851	//
852	// 语义：
853	//   - 参数合法时，已成功的退款编号优先判定：目标结算与原因都相同返回 duplicate
854	//     及原退款记录（不再入账）；任一不同返回 conflict。
855	//   - 新退款编号：找不到成功结算（含原付款只曾失败）返回 not_found；
856	//     该结算已被其他退款编号退回返回 refunded，不增加余额。
857	//   - 成功时把原记录的 charged（含当时已扣手续费）全额退回原账户、原资产；
858	//     退款金额与去向完全由原结算确定，原结算记录及其编号、顺序保持不变。
859	//   - 失败申请不占用退款编号，之后可修改原因或目标再提交。
860	func (l *Ledger) Refund(batch RefundBatch) (*RefundBatchResult, error) {
861		if err := l.beginOp(); err != nil {
862			return nil, err
863		}
864		defer l.endOp()
865		out := &RefundBatchResult{Results: make([]RefundResult, 0, len(batch.Refunds))}
866	
867		l.reg.mu.Lock()
868		defer l.reg.mu.Unlock()
869	
870		for i := range batch.Refunds {
871			req := &batch.Refunds[i]
872			res := RefundResult{ID: req.ID}
873	
874			// 1. 参数校验：退款编号、原付款编号、原因三者都必须非空。
875			//    未通过的编号不占用退款资格。
876			if req.ID == "" {
877				res.Status = StatusInvalid
878				res.Reason = reasonEmptyRefundID
879				out.Results = append(out.Results, res)
880				continue
881			}
882			if req.SettlementID == "" {
883				res.Status = StatusInvalid
884				res.Reason = reasonEmptySettlement
885				out.Results = append(out.Results, res)
886				continue
887			}
888			if req.Reason == "" {
889				res.Status = StatusInvalid
890				res.Reason = reasonEmptyReason
891				out.Results = append(out.Results, res)
892				continue
893			}
894	
895			// 2. 已成功退款编号优先判定：目标与原因都相同则幂等返回原退款记录；
896			//    任一不同则冲突。两者都不再入账。本批次内先成功的同编号项也在此可见。
897			if prior, exists := l.findRefund(req.ID); exists {
898				if prior.SettlementID == req.SettlementID && prior.Reason == req.Reason {
899					cp := prior
900					res.Status = StatusDuplicate
901					res.Reason = prior.Reason
902					res.SettlementID = prior.SettlementID
903					res.Account = prior.Account
904					res.Asset = prior.Asset
905					res.Charged = prior.Charged
906					res.Record = &cp
907				} else {
908					res.Status = StatusConflict
909					res.Reason = reasonRefundConflict
910				}
911				out.Results = append(out.Results, res)
912				continue
913			}
914	
915			// 3. 新退款编号：目标必须是一笔成功结算（原付款只曾失败也算不存在）。
916			target, exists := l.findRecord(req.SettlementID)
917			if !exists {
918				res.Status = StatusNotFound
919				res.Reason = fmt.Sprintf(reasonSettlementGone, req.SettlementID)
920				out.Results = append(out.Results, res)
921				continue
922			}
923	
924			// 4. 每笔原付款最多退回一次：已被其他退款编号退回则报告已退款，不加余额。
925			if prior, refunded := l.findRefundOfSettlement(req.SettlementID); refunded {
926				res.Status = StatusAlreadyRefunded
927				res.Reason = fmt.Sprintf(reasonAlreadyRefunded, req.SettlementID, prior.ID)
928				out.Results = append(out.Results, res)
929				continue
930			}
931	
932			// 5. 全额退回原账户、原资产（amount 与当时手续费一并退回），
933			//    与退款记录在同一个原子写入中落盘；保存失败回滚该项。
934			rec := RefundRecord{
935				ID:           req.ID,
936				SettlementID: target.ID,
937				Reason:       req.Reason,
938				Account:      target.Account,
939				Asset:        target.Asset,
940				Amount:       target.Amount,
941				Fee:          target.Fee,
942				Charged:      target.Charged,
943				AfterSeq:     int64(len(l.reg.state.Settlements)),
944				Seq:          int64(len(l.reg.state.Refunds)) + 1,
945			}
946			key := balanceKey{target.Account, target.Asset}
947			bal := l.reg.state.Balances[key]
948			rollback := l.stageRefund(key, bal+target.Charged, rec)
949			if err := l.persistLocked(); err != nil {
950				rollback()
951				res.Status = StatusStorage
952				res.Reason = err.Error()
953			} else {
954				cp := rec
955				res.Status = StatusRefundSuccess
956				res.Reason = rec.Reason
957				res.SettlementID = rec.SettlementID
958				res.Account = rec.Account
959				res.Asset = rec.Asset
960				res.Charged = rec.Charged
961				res.Record = &cp
962			}
963			out.Results = append(out.Results, res)
964		}
965		return out, nil
966	}
967	
968	// stageRefund 应用一笔退款（余额增加 + 记录追加），返回回滚函数。
969	func (l *Ledger) stageRefund(key balanceKey, newBal int64, rec RefundRecord) func() {
970		oldBal, hadKey := l.reg.state.Balances[key]
971		oldLen := len(l.reg.state.Refunds)
972		l.reg.state.Balances[key] = newBal
973		l.reg.state.Refunds = append(l.reg.state.Refunds, rec)
974		return func() {
975			if hadKey {
976				l.reg.state.Balances[key] = oldBal
977			} else {
978				delete(l.reg.state.Balances, key)
979			}
980			l.reg.state.Refunds = l.reg.state.Refunds[:oldLen]
981		}
982	}
983	
984	func (l *Ledger) findRefund(id string) (RefundRecord, bool) {
985		// 退款按成功顺序追加且 ID 唯一；单机账本量级直接扫描。
986		for _, r := range l.stateView().Refunds {
987			if r.ID == id {
988				return r, true
989			}
990		}
991		return RefundRecord{}, false
992	}
993	
994	// findRefundOfSettlement 返回退回指定结算的那笔退款（每笔结算最多一笔）。
995	func (l *Ledger) findRefundOfSettlement(settlementID string) (RefundRecord, bool) {
996		for _, r := range l.stateView().Refunds {
997			if r.SettlementID == settlementID {
998				return r, true
999			}
1000		}
1001		return RefundRecord{}, false
1002	}
1003	
1004	func (l *Ledger) stateView() *ledgerState { return l.reg.state }
1005	
1006	func (l *Ledger) findRecord(id string) (Record, bool) {
1007		// 记录按成功顺序追加且 ID 唯一；条目规模在单机账本量级，直接扫描。
1008		for _, r := range l.stateView().Settlements {
1009			if r.ID == id {
1010				return r, true
1011			}
1012		}
1013		return Record{}, false
1014	}
1015	
1016	// sameRequest 比较全部付款字段与费率。付款字段：账户、付款方、资产、金额、nonce。
1017	func sameRequest(r Record, it *PaymentIntent, amount int64, feeBps int) bool {
1018		return r.Account == it.Account &&
1019			r.Paymaster == it.Paymaster &&
1020			r.Asset == it.Asset &&
1021			r.Amount == amount &&
1022			r.Nonce == it.Nonce &&
1023			r.FeeBps == feeBps
1024	}
1025	
1026	// Query 返回余额视图（按账户、资产排序，保证确定性）与按成功先后排列的记录。
1027	func (l *Ledger) Query() (*Snapshot, error) {
1028		if err := l.beginOp(); err != nil {
1029			return nil, err
1030		}
1031		defer l.endOp()
1032		l.reg.mu.Lock()
1033		defer l.reg.mu.Unlock()
1034	
1035		st := l.stateView()
1036		bals := make([]BalanceView, 0, len(st.Balances))
1037		for k, v := range st.Balances {
1038			bals = append(bals, BalanceView{Account: k.account, Asset: k.asset, Balance: v})
1039		}
1040		sortBalances(bals)
1041		recs := make([]Record, len(st.Settlements))
1042		copy(recs, st.Settlements)
1043		refunds := make([]RefundRecord, len(st.Refunds))
1044		copy(refunds, st.Refunds)
1045		return &Snapshot{Balances: bals, Settlements: recs, Refunds: refunds}, nil
1046	}
1047	
1048	// Balance 返回单个 (账户, 资产) 组合的余额；组合不存在按 0 处理。
1049	func (l *Ledger) Balance(account, asset string) (int64, error) {
1050		if err := l.beginOp(); err != nil {
1051			return 0, err
1052		}
1053		defer l.endOp()
1054		l.reg.mu.Lock()
1055		defer l.reg.mu.Unlock()
1056		return l.stateView().Balances[balanceKey{account, asset}], nil
1057	}
1058	
1059	func sortBalances(bals []BalanceView) {
1060		sort.Slice(bals, func(i, j int) bool {
1061			if bals[i].Account != bals[j].Account {
1062				return bals[i].Account < bals[j].Account
1063			}
1064			return bals[i].Asset < bals[j].Asset
1065		})
1066	}
1067	
1068	// persistLocked 将当前状态原子写入磁盘；调用方必须持有 reg.mu。
1069	func (l *Ledger) persistLocked() error {
1070		if l.reg.failHook != nil && l.reg.failHook.FailNextPersist() {
1071			return ledgerError(ErrStorage, "injected write failure")
1072		}
1073		return atomicWrite(l.path, l.stateView())
1074	}
1075	
1076	// SetFailHook 为该路径的账本安装存储故障注入，仅用于测试。
1077	func SetFailHook(l *Ledger, fw FailWriter) {
1078		l.reg.failHook = fw
1079	}
1080

