946			{"empty asset", func() FlowEntry { e := validFlowEntry(0); e.Asset = ""; return e }(), "asset"},
947			{"zero amount", func() FlowEntry { e := validFlowEntry(0); e.Amount = 0; return e }(), "amount"},
948			{"negative amount", func() FlowEntry { e := validFlowEntry(0); e.Amount = -1; return e }(), "amount"},
949			{"negative fee", func() FlowEntry { e := validFlowEntry(0); e.Fee = -1; return e }(), "fee"},
