		if r.Status != want[i] {
			t.Fatalf("result %d=%s want %s", i, r.Status, want[i])
		}
	}
	// out_of_scope 携带账本记录与关联（不切断）。
	if rep.Results[0].Record == nil || rep.Results[0].Record.RefundID != "r1" {
		t.Fatalf("p1 out_of_scope record link: %+v", rep.Results[0].Record)
	}
